#include "lua_agent.hpp"
#include "test_support.hpp"
#include <filesystem>
#include <fstream>
using namespace g9;int main(){auto p=std::filesystem::temp_directory_path()/"g9-lua-agent-test.lua";{std::ofstream f(p);f<<R"lua(
local safe = io == nil and os == nil and package == nil and debug == nil and print == nil and dofile == nil and loadfile == nil and load == nil
return { model={path='m.gguf',context_size=1024,batch_size=128,gpu_layers=0,threads=1}, generation={thinking=false,max_tokens=16,temperature=.7,top_p=.9,top_k=20,min_p=0,repeat_penalty=1,repeat_last_n=8,seed=1}, loop={max_steps=4,max_tool_calls_per_step=2,max_tool_result_bytes=4096}, workspace={default_access='rw',deny={'.env'},scopes={{path='docs',access='r'}}}, guardrails={profile='review',command_sandbox='strict'}, before_prompt=function(r) if not safe then error('unsafe globals') end;r.prompt='hook:'..r.prompt;return r end, build_messages=function(r)return{{role='user',content=r.prompt}}end, render_prompt=function(messages,g,t,h)return '<s>'..messages[1].content end, generation_settings=function(r)return {thinking=false,max_tokens=8} end, after_response=function(r)r.output='post:'..r.output;return r end }
)lua";}LuaAgent a(p,{});auto r=a.before_prompt(AgentRequest{"x"});CHECK_EQ(r.prompt,"hook:x");CHECK_EQ(a.workspace_policy().deny.size(),1u);CHECK_EQ(a.workspace_policy().scopes.size(),1u);CHECK_EQ(a.guardrail_policy().profile,"review");auto rendered=a.render_prompt(a.build_messages(r),a.generation(),JsonValue::array{},JsonValue::array{});CHECK_EQ(rendered,"<s>hook:x");a.set_thinking(true);CHECK(a.generation_settings(r).thinking);AgentResponse response;response.output="ok";auto post=a.after_response(response);CHECK_EQ(post.output,"post:ok");std::filesystem::remove(p);return test_support::finish();}
